void rsr_ext_runtime (void * arg)
{
  if(RSR_ENGINE_RUNNING && os_flg_state (rsr_vars.flg_start))
  {
  	rsr_timing_reset (); 
  	rsr_notify_start (TRUE);
  }

  #if DBG_RSR == 1
	  dbg_tx_text ("rsr extend runtime") ;
  #endif
}


